export type ErrorKind = "invalid_input" | "not_found" | "upstream_unavailable" | "internal";

export class AppError extends Error {
  constructor(
    readonly kind: ErrorKind,
    message: string,
    readonly fields: Record<string, unknown> = {},
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "AppError";
  }
}

export function wrap(err: unknown, message: string, fields: Record<string, unknown> = {}): AppError {
  const kind = err instanceof AppError ? err.kind : "internal";
  return new AppError(kind, message, fields, { cause: err });
}

export function errorChain(err: unknown): string {
  const parts: string[] = [];
  let current: unknown = err;
  for (let depth = 0; current !== undefined && depth < 8; depth++) {
    parts.push(current instanceof Error ? current.message : String(current));
    current = current instanceof Error ? current.cause : undefined;
  }
  return parts.join(": ");
}

export function collectFields(err: unknown): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  let current: unknown = err;
  for (let depth = 0; current instanceof Error && depth < 8; depth++) {
    if (current instanceof AppError) {
      for (const [k, v] of Object.entries(current.fields)) {
        if (!(k in out)) out[k] = v;
      }
    }
    current = current.cause;
  }
  return out;
}

import { AppError, wrap } from "./errors";

export interface Campaign { id: string; advertiserId: string; dailyBudgetMicros: number; }
export interface SpendRow { campaignId: string; day: string; spendMicros: number; impressions: number; }

export interface CampaignStore { get(id: string): Promise<Campaign | null>; }
export interface WarehouseClient { query<T>(sql: string, params: unknown[]): Promise<T[]>; }

export class SpendReportService {
  constructor(
    private readonly campaigns: CampaignStore,
    private readonly warehouse: WarehouseClient,
  ) {}

  async dailySpend(campaignId: string, from: string, to: string): Promise<SpendRow[]> {
    if (from > to) {
      throw new AppError("invalid_input", "from must not be after to", { from, to });
    }

    let campaign: Campaign | null;
    try {
      campaign = await this.campaigns.get(campaignId);
    } catch (err) {
      throw wrap(err, "loading campaign", { campaignId });
    }
    if (!campaign) {
      throw new AppError("not_found", `campaign ${campaignId} not found`, { campaignId });
    }

    try {
      return await this.warehouse.query<SpendRow>(
        `SELECT campaign_id AS "campaignId", day, spend_micros AS "spendMicros", impressions
         FROM daily_campaign_spend WHERE campaign_id = $1 AND day BETWEEN $2 AND $3 ORDER BY day`,
        [campaignId, from, to],
      );
    } catch (err) {
      throw new AppError("upstream_unavailable", "querying spend warehouse", { campaignId, from, to }, { cause: err });
    }
  }
}

import { Request, Response } from "express";
import { AppError, collectFields, errorChain } from "./errors";
import { SpendReportService } from "./spendReportService";

export interface Logger { error(msg: string, fields: Record<string, unknown>): void; }

const STATUS: Record<string, number> = {
  invalid_input: 400,
  not_found: 404,
  upstream_unavailable: 503,
  internal: 500,
};

export function spendHandler(service: SpendReportService, log: Logger) {
  return async (req: Request, res: Response) => {
    const { campaignId } = req.params;
    const from = String(req.query.from ?? "");
    const to = String(req.query.to ?? "");
    try {
      const rows = await service.dailySpend(campaignId, from, to);
      res.json({ campaignId, rows });
    } catch (err) {
      const kind = err instanceof AppError ? err.kind : "internal";
      const status = STATUS[kind] ?? 500;
      if (status >= 500) {
        log.error("spend report failed", {
          route: "GET /campaigns/:campaignId/spend",
          error: errorChain(err),
          ...collectFields(err),
        });
      }
      const publicMessage = status >= 500 ? "spend report temporarily unavailable" : (err as Error).message;
      res.status(status).json({ error: kind, message: publicMessage });
    }
  };
}
